<template>
  <section class="user-reference">
    <header class="user-reference-hero"><div class="user-reference-heading"><span><icon-user-group /></span><div><h1>用户管理</h1><p>管理成员账号、审核申请与账号状态</p></div></div><svg preserveAspectRatio="none" viewBox="0 0 600 130" aria-hidden="true"><path d="M0 130C240 160 230-10 600 0v130" fill="currentColor" opacity=".07"/><path d="M100 130C300 125 280 0 600 16v114" fill="currentColor" opacity=".08"/></svg><a-space><a-button @click="importVisible = true"><template #icon><icon-download /></template>导入用户</a-button><a-button type="primary" :disabled="!canAdd" @click="$emit('create')"><template #icon><icon-plus /></template>添加用户</a-button></a-space></header>
    <div class="user-reference-metrics"><article v-for="metric in metrics" :key="metric.label" :class="metric.tone"><span><component :is="metric.icon" /></span><div><small>{{ metric.label }}</small><strong>{{ unavailable ? '—' : metric.value.toLocaleString() }}</strong></div><p>{{ metric.hint }}</p></article></div>
    <div class="user-reference-tabs" role="group" aria-label="用户审核状态"><button v-for="item in tabs" :key="item.key" :class="{ active: tab===item.key }" @click="selectTab(item.key)">{{ item.label }} <span>({{ unavailable ? '—' : item.count }})</span></button><a-tooltip content="账号禁用与审核状态独立，禁用用户可能同时已通过、待审核或已驳回。"><icon-info-circle /></a-tooltip></div>
    <form class="user-reference-filters" @submit.prevent="applyFilters"><a-input v-model="draft.query" allow-clear placeholder="搜索用户名/姓名/邮箱/手机号" :input-attrs="{ 'aria-label': '搜索用户' }"><template #prefix><icon-search /></template></a-input><div class="user-reference-field"><span>所属组织</span><a-select v-model="draft.organization" aria-label="所属组织筛选"><a-option value="">全部组织</a-option><a-option v-for="group in organizations" :key="group" :value="group">{{ group }}</a-option></a-select></div><div class="user-reference-field"><span>角色类型</span><a-select v-model="draft.role" aria-label="角色类型筛选"><a-option value="">全部角色</a-option><a-option value="admin">管理员</a-option><a-option value="member">普通成员</a-option></a-select></div><div class="user-reference-field"><span>账号状态</span><a-select v-model="draft.account" aria-label="账号状态筛选"><a-option value="">全部状态</a-option><a-option value="enabled">已启用</a-option><a-option value="disabled">已禁用</a-option></a-select></div><div class="user-reference-field"><span>审核状态</span><a-select v-model="draft.approval" aria-label="审核状态筛选"><a-option value="">全部审核状态</a-option><a-option value="pending">待审核</a-option><a-option value="approved">已通过</a-option><a-option value="rejected">已驳回</a-option><a-option value="unknown">未标明</a-option></a-select></div><div><a-button @click="resetFilters"><template #icon><icon-refresh /></template>重置</a-button><a-button type="primary" html-type="submit"><template #icon><icon-search /></template>查询</a-button></div></form>
    <a-alert v-if="error" type="error">{{ error }} <a-button type="text" @click="$emit('refresh')">重试</a-button></a-alert>
    <main class="user-reference-list"><a-table class="user-reference-table" row-key="id" :data="pageRows" :loading="loading" :pagination="false" :bordered="false" :scroll="{ x: 1180 }"><template #columns>
      <a-table-column title="用户ID" data-index="id" :width="65" />
      <a-table-column title="用户信息" :width="185"><template #cell="{ record }"><button class="user-reference-identity" @click="showDetails(record)"><span :class="avatarTone(record)">{{ initial(record) }}</span><div><strong>{{ record.username }} <icon-safe v-if="record.is_staff" /></strong><small>{{ displayName(record) }}</small></div></button></template></a-table-column>
      <a-table-column title="联系方式" :width="220"><template #cell="{ record }"><div class="user-reference-contact"><span :title="record.email"><icon-email />{{ record.email || '未填写邮箱' }}</span><span v-if="record.phone_number"><icon-phone />{{ maskPhone(record.phone_number) }}</span></div></template></a-table-column>
      <a-table-column title="所属组织" :width="120"><template #cell="{ record }"><span class="user-reference-organizations" :title="userOrganizations(record).join('、')">{{ userOrganizations(record).join('、') || '未分配' }}</span></template></a-table-column>
      <a-table-column title="角色" :width="95"><template #cell="{ record }"><a-tag :color="record.is_staff ? 'green' : 'gray'">{{ record.is_staff ? '管理员' : '普通成员' }}</a-tag></template></a-table-column>
      <a-table-column title="最近登录" :width="135"><template #cell="{ record }"><a-tooltip :content="record.last_login === undefined ? '当前接口未返回最近登录时间' : loginText(record.last_login)"><span class="user-reference-login">{{ loginText(record.last_login) }}</span></a-tooltip></template></a-table-column>
      <a-table-column title="账号状态" :width="85"><template #cell="{ record }"><a-tag :color="record.is_active ? 'green' : 'gray'"><i class="user-reference-dot" />{{ record.is_active ? '已启用' : '已禁用' }}</a-tag></template></a-table-column>
      <a-table-column title="审核状态" :width="85"><template #cell="{ record }"><a-tag :color="approvalColor(record)">{{ approvalLabel(record) }}</a-tag></template></a-table-column>
      <a-table-column title="操作" :width="190" fixed="right"><template #cell="{ record }"><div class="user-reference-row-actions"><a-button type="text" size="mini" :aria-label="'查看 ' + record.username" @click="showDetails(record)">查看</a-button><a-button type="text" size="mini" :disabled="!canChange" :aria-label="'编辑 ' + record.username" @click="$emit('edit', record)">编辑</a-button><a-button type="text" size="mini" :disabled="!canChange" :aria-label="'权限 ' + record.username" @click="$emit('permissions', record)">权限</a-button><a-button type="text" size="mini" :class="record.is_active ? 'user-reference-danger' : 'user-reference-enable'" :disabled="!canChange || record.id === auth.user?.id" :aria-label="(record.is_active ? '禁用 ' : '启用 ') + record.username" @click="$emit('toggle', record)">{{ record.is_active ? '禁用' : '启用' }}</a-button><a-dropdown @select="(value: string) => more(value, record)"><a-button type="text" size="mini" :aria-label="'更多 ' + record.username"><icon-more-vertical /></a-button><template #content><a-doption value="logs">查看操作记录</a-doption><a-doption v-if="approvalOf(record)!=='approved'" value="approve" :disabled="!canChange">审核通过</a-doption><a-doption v-if="approvalOf(record)!=='rejected'" value="reject" :disabled="!canChange || record.id === auth.user?.id">驳回申请</a-doption><a-doption value="delete" :disabled="!canDelete || record.id === auth.user?.id">删除用户</a-doption></template></a-dropdown></div></template></a-table-column>
    </template><template #empty><div class="user-reference-empty"><icon-user-group /><strong>{{ error ? '用户列表加载失败' : filteredActive ? '没有匹配的用户' : '暂无用户记录' }}</strong><p>调整筛选条件，或添加新的团队成员</p><a-button v-if="!error && filteredActive" @click="resetFilters">重置筛选</a-button></div></template></a-table>
    <footer class="user-reference-pagination"><span>共 {{ filtered.length.toLocaleString() }} 条</span><a-pagination :current="page" :page-size="pageSize" :total="filtered.length" show-page-size size="small" :page-size-options="[10,20,50]" @change="page = $event" @page-size-change="pageSize = $event; page = 1" /></footer></main>
    <a-drawer v-model:visible="detailVisible" title="用户详情" :width="460" class="fc-drawer" :footer="false"><template v-if="selected"><div class="user-reference-detail-heading"><span :class="avatarTone(selected)">{{ initial(selected) }}</span><div><h2>{{ selected.username }}</h2><p>{{ displayName(selected) }}</p></div></div><a-descriptions :column="1" bordered size="medium"><a-descriptions-item label="用户 ID">{{ selected.id }}</a-descriptions-item><a-descriptions-item label="邮箱">{{ selected.email || '未填写' }}</a-descriptions-item><a-descriptions-item label="手机号">{{ selected.phone_number || '未填写' }}</a-descriptions-item><a-descriptions-item label="所属组织">{{ userOrganizations(selected).join('、') || '未分配' }}</a-descriptions-item><a-descriptions-item label="角色">{{ selected.is_staff ? '管理员' : '普通成员' }}</a-descriptions-item><a-descriptions-item label="账号状态">{{ selected.is_active ? '已启用' : '已禁用' }}</a-descriptions-item><a-descriptions-item label="审核状态">{{ approvalLabel(selected) }}</a-descriptions-item><a-descriptions-item label="最近登录">{{ loginText(selected.last_login) }}</a-descriptions-item><a-descriptions-item label="审核说明">{{ selected.approval_review_note || '暂无说明' }}</a-descriptions-item></a-descriptions><a-button style="margin-top:20px" @click="detailVisible = false; $emit('logs', selected)">查看操作记录</a-button></template></a-drawer>
    <a-modal v-model:visible="importVisible" title="导入用户" :width="480" :footer="false"><a-alert>当前服务尚未提供批量用户导入接口。</a-alert><p class="user-reference-import-note">可使用“添加用户”创建成员账号，再分别管理组织、审核状态和权限。本页面不会从文件自动创建账号或授予管理员权限。</p><a-button type="primary" :disabled="!canAdd" @click="importVisible = false; $emit('create')">添加用户</a-button></a-modal>
  </section>
</template>
<script setup lang="ts">
import { computed, ref, reactive, watch } from 'vue';
import { useAuthStore } from '@/store/authStore';
import type { User } from '@/services/userService';
import { approvalOf, userOverview, filterUsers, userOrganizations, maskPhone, loginText, type UserTab, type UserFilters } from '../userPresentation';
import { IconUserGroup, IconDownload, IconPlus, IconClockCircle, IconCheckCircle, IconSafe, IconSearch, IconRefresh, IconEmail, IconPhone, IconMoreVertical, IconInfoCircle } from '@arco-design/web-vue/es/icon';
import './user-reference.css';
const props=defineProps<{ users:User[]; loading:boolean; error:string }>();
const emit=defineEmits<{ create:[]; refresh:[]; edit:[user:User]; permissions:[user:User]; toggle:[user:User]; logs:[user:User]; approve:[user:User]; reject:[user:User]; delete:[user:User] }>();
const auth=useAuthStore(); const canAdd=computed(()=>auth.hasPermission('auth.add_user')),canChange=computed(()=>auth.hasPermission('auth.change_user')),canDelete=computed(()=>auth.hasPermission('auth.delete_user'));
const defaults=():UserFilters=>({ query:'',organization:'',role:'',account:'',approval:'' });
const draft=reactive(defaults()), applied=ref(defaults()),tab=ref<UserTab>('all'),page=ref(1),pageSize=ref(10); const importVisible=ref(false),detailVisible=ref(false),selected=ref<User|null>(null);
const overview=computed(()=>userOverview(props.users)); const unavailable=computed(()=>!!props.error || (props.loading&&!props.users.length));
const organizations=computed(()=>[...new Set(props.users.flatMap(userOrganizations))].sort((a,b)=>a.localeCompare(b,'zh-CN')));
const filtered=computed(()=>filterUsers(props.users,applied.value,tab.value)); const pageRows=computed(()=>filtered.value.slice((page.value-1)*pageSize.value,page.value*pageSize.value));
const filteredActive=computed(()=>tab.value!=='all'||Object.values(applied.value).some(Boolean));
const metrics=computed(()=>[{label:'全部用户',value:overview.value.all,icon:IconUserGroup,tone:'teal',hint:'当前可读取的用户总量'},{label:'待审核',value:overview.value.pending,icon:IconClockCircle,tone:'orange',hint:'等待管理员审核'},{label:'已启用',value:overview.value.active,icon:IconCheckCircle,tone:'green',hint:'账号处于启用状态'},{label:'管理员',value:overview.value.administrators,icon:IconSafe,tone:'purple',hint:'具有管理员标识'}]);
const tabs=computed(()=>[{key:'all' as UserTab,label:'全部',count:overview.value.all},{key:'pending' as UserTab,label:'待审核',count:overview.value.pending},{key:'approved' as UserTab,label:'已通过',count:overview.value.approved},{key:'rejected' as UserTab,label:'已驳回',count:overview.value.rejected},{key:'disabled' as UserTab,label:'已禁用',count:overview.value.disabled}]);
function applyFilters(){applied.value={...draft};page.value=1;}
function resetFilters(){Object.assign(draft,defaults());tab.value='all';applyFilters();}
function selectTab(value:UserTab){tab.value=value;draft.account='';draft.approval='';applyFilters();}
const displayName=(user:User)=>user.real_name||[user.last_name,user.first_name].filter(Boolean).join('')||'未填写姓名';
const initial=(user:User)=>(user.real_name||user.username||'?').slice(0,1).toUpperCase();
const avatarTone=(user:User)=>['teal','blue','purple','cyan'][user.id%4];
const approvalLabel=(user:User)=>({pending:'待审核',approved:'已通过',rejected:'已驳回',unknown:'未标明'}[approvalOf(user)]||'未标明');
const approvalColor=(user:User)=>({pending:'orange',approved:'green',rejected:'red',unknown:'gray'}[approvalOf(user)]||'gray');
function showDetails(user:User){selected.value=user;detailVisible.value=true;}
function more(value:string,user:User){if(value==='logs')emit('logs',user);else if(value==='approve'&&canChange.value)emit('approve',user);else if(value==='reject'&&canChange.value)emit('reject',user);else if(value==='delete'&&canDelete.value)emit('delete',user);}
watch(()=>filtered.value.length,count=>{if((page.value-1)*pageSize.value>=count)page.value=1;});
watch(()=>props.users,users=>{if(selected.value){selected.value=users.find(user=>user.id===selected.value?.id)||null;if(!selected.value)detailVisible.value=false;}});
</script>
